<?php
require __DIR__.'/../config/auth.php';requireAdmin();require __DIR__.'/../config/db.php';require __DIR__.'/../config/layout.php';verify_csrf();
$msg='';$err='';$sectores=$pdo->query("SELECT id,nombre,slug,orden FROM sectores WHERE slug<>'gerencia' ORDER BY orden,nombre")->fetchAll();
function assignSector(PDO $pdo,int $uid,string $role,int $sid): void {$pdo->prepare('DELETE FROM usuario_sector WHERE usuario_id=?')->execute([$uid]);if($role==='admin'){$pdo->prepare('INSERT INTO usuario_sector(usuario_id,sector_id,puede_ver,puede_editar) SELECT ?,id,1,1 FROM sectores')->execute([$uid]);return;}if($sid>0){$edit=in_array($role,['supervisor','ventas'],true)?1:0;$pdo->prepare('INSERT INTO usuario_sector(usuario_id,sector_id,puede_ver,puede_editar) VALUES(?,?,1,?)')->execute([$uid,$sid,$edit]);}$sgi=(int)$pdo->query("SELECT id FROM sectores WHERE slug='sgi' LIMIT 1")->fetchColumn();if($sgi&&$sgi!==$sid)$pdo->prepare('INSERT INTO usuario_sector(usuario_id,sector_id,puede_ver,puede_editar) VALUES(?,?,1,0) ON DUPLICATE KEY UPDATE puede_ver=1')->execute([$uid,$sgi]);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$a=$_POST['accion']??'';
  if($a==='crear'){$n=trim($_POST['nombre']??'');$e=strtolower(trim($_POST['email']??''));$p=$_POST['password']??'';$r=$_POST['rol']??'operador';$sid=(int)($_POST['sector_id']??0);if($n===''||$e===''||$p==='')throw new RuntimeException('Completá nombre, correo y contraseña.');$st=$pdo->prepare('INSERT INTO usuarios(nombre,email,password,rol,activo) VALUES(?,?,?,?,1)');$st->execute([$n,$e,password_hash($p,PASSWORD_DEFAULT),$r]);$uid=(int)$pdo->lastInsertId();assignSector($pdo,$uid,$r,$sid);registrarActividad($pdo,'crear_usuario',$e);$msg='Usuario creado correctamente.';}
  if($a==='editar'){$id=(int)($_POST['id']??0);$n=trim($_POST['nombre']??'');$e=strtolower(trim($_POST['email']??''));$r=$_POST['rol']??'operador';$sid=(int)($_POST['sector_id']??0);$p=$_POST['password']??'';if($id<=0||$n===''||$e==='')throw new RuntimeException('Datos incompletos.');if($p!==''){$st=$pdo->prepare('UPDATE usuarios SET nombre=?,email=?,rol=?,password=? WHERE id=?');$st->execute([$n,$e,$r,password_hash($p,PASSWORD_DEFAULT),$id]);}else{$st=$pdo->prepare('UPDATE usuarios SET nombre=?,email=?,rol=? WHERE id=?');$st->execute([$n,$e,$r,$id]);}assignSector($pdo,$id,$r,$sid);registrarActividad($pdo,'editar_usuario',$e);$msg='Usuario actualizado.';}
  if($a==='estado'){$id=(int)($_POST['id']??0);if($id===(int)$_SESSION['usuario_id'])throw new RuntimeException('No podés desactivar tu propia cuenta.');$pdo->prepare('UPDATE usuarios SET activo=IF(activo=1,0,1) WHERE id=?')->execute([$id]);registrarActividad($pdo,'cambiar_estado_usuario',"Usuario $id");$msg='Estado actualizado.';}
  if($a==='eliminar'){$id=(int)($_POST['id']??0);if($id===(int)$_SESSION['usuario_id'])throw new RuntimeException('No podés eliminar tu propia cuenta.');$pdo->prepare('DELETE FROM usuarios WHERE id=?')->execute([$id]);registrarActividad($pdo,'eliminar_usuario',"Usuario $id");$msg='Usuario eliminado.';}
 }catch(Throwable $e){$err=str_contains($e->getMessage(),'Duplicate')?'Ese correo ya está registrado.':$e->getMessage();}
}
$usuarios=$pdo->query("SELECT u.*,(SELECT s.id FROM usuario_sector us JOIN sectores s ON s.id=us.sector_id WHERE us.usuario_id=u.id AND s.slug<>'sgi' ORDER BY us.puede_editar DESC,s.orden LIMIT 1) sector_id,(SELECT s.nombre FROM usuario_sector us JOIN sectores s ON s.id=us.sector_id WHERE us.usuario_id=u.id AND s.slug<>'sgi' ORDER BY us.puede_editar DESC,s.orden LIMIT 1) sector FROM usuarios u ORDER BY FIELD(u.rol,'admin','supervisor','ventas','operador','usuario'),u.nombre")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios | NASER</title><link rel="stylesheet" href="<?=app_url('/style.css')?>"></head><body><div class="app"><?php sidebar($pdo,'usuarios');?><main class="content"><header class="section-top"><div><p class="eyebrow">ADMINISTRACIÓN</p><h1>Usuarios y permisos</h1><p>Admin total, supervisores por sector y operadores con acceso de lectura.</p></div></header><?php if($msg):?><div class="alert success"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=h($err)?></div><?php endif;?><div class="admin-layout"><section class="form-panel"><p class="eyebrow">NUEVO USUARIO</p><h2>Crear acceso</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="accion" value="crear"><label>Nombre<input name="nombre" required></label><label>Correo<input type="email" name="email" required></label><label>Contraseña<input type="password" name="password" required></label><label>Rol<select name="rol"><option value="supervisor">Supervisor</option><option value="operador">Operador</option><option value="ventas">Ventas</option><option value="admin">Administrador / Gerencia</option></select></label><label>Sector asignado<select name="sector_id"><option value="0">Sin sector</option><?php foreach($sectores as $s):?><option value="<?=$s['id']?>"><?=h($s['nombre'])?></option><?php endforeach;?></select></label><button class="btn primary">Crear usuario</button></form><div class="permission-note"><strong>Regla de permisos</strong><p>Supervisor: edita su sector. Operador: lectura de su sector. Ventas: edita Ventas. Todos pueden consultar SGI. Administrador: acceso total.</p></div></section><section class="table-panel"><div class="section-head"><div><p class="eyebrow">USUARIOS</p><h2>Accesos del sistema</h2></div><span class="count-pill"><?=count($usuarios)?> usuario(s)</span></div><div class="user-list"><?php foreach($usuarios as $u):?><details class="user-item"><summary><div><strong><?=h($u['nombre'])?></strong><small><?=h($u['email'])?> · <?=h($u['rol']==='admin'?'Administrador':ucfirst($u['rol']))?> · <?=h($u['rol']==='admin'?'Todos los sectores':($u['sector']??'Sin sector'))?></small></div><span class="<?=$u['activo']?'state-on':'state-off'?>"><?=$u['activo']?'Activo':'Inactivo'?></span></summary><form method="post" class="form-grid user-edit"><?=csrf_field()?><input type="hidden" name="accion" value="editar"><input type="hidden" name="id" value="<?=$u['id']?>"><div class="form-row"><label>Nombre<input name="nombre" value="<?=h($u['nombre'])?>" required></label><label>Correo<input type="email" name="email" value="<?=h($u['email'])?>" required></label></div><div class="form-row"><label>Rol<select name="rol"><?php foreach(['admin'=>'Administrador','supervisor'=>'Supervisor','ventas'=>'Ventas','operador'=>'Operador'] as $v=>$n):?><option value="<?=$v?>" <?=$u['rol']===$v?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><label>Sector<select name="sector_id"><option value="0">Sin sector</option><?php foreach($sectores as $s):?><option value="<?=$s['id']?>" <?=(int)$u['sector_id']===(int)$s['id']?'selected':''?>><?=h($s['nombre'])?></option><?php endforeach;?></select></label></div><label>Nueva contraseña <small>(dejá vacío para conservarla)</small><input type="password" name="password"></label><button class="btn secondary">Guardar cambios</button></form><div class="user-actions"><form method="post"><?=csrf_field()?><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn small secondary" <?=$u['id']===$_SESSION['usuario_id']?'disabled':''?>><?=$u['activo']?'Desactivar':'Activar'?></button></form><form method="post" onsubmit="return confirm('¿Eliminar este usuario?')"><?=csrf_field()?><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn small danger" <?=$u['id']===$_SESSION['usuario_id']?'disabled':''?>>Eliminar</button></form></div></details><?php endforeach;?></div></section></div></main></div></body></html>
